(6288608, 930544, 114225, '<td valign="top">Nice mood with the dark clouds and the tree branch moving in the wind (ok, it may not be moving, but I imagine it that way).</td>', 'Nice mood with the dark clouds and the tree branch moving in the wind (ok, it may not be moving, but I imagine it that way).', '2011-01-19 17:32:45.000000', NULL, 1),
(6288609, 930804, 114225, '<td valign="top">Heh, cutely done. Nice use of bokeh and a well balanced scene.</td>', 'Heh, cutely done. Nice use of bokeh and a well balanced scene.', '2011-01-19 17:33:16.000000', NULL, 1),
(6288611, 930731, 114225, '<td valign="top">One of my favorite types of lamps. Interesting choice to go for a daytime shot with this. I think it could have setup a nice mood with it dimly lit at dusk.</td>', 'One of my favorite types of lamps. Interesting choice to go for a daytime shot with this. I think it could have setup a nice mood with it dimly lit at dusk.', '2011-01-19 17:34:00.000000', NULL, 1),
(6288612, 930787, 114225, '<td valign="top">Interesting choice of setup here. Being in what looks like a basement gives this a real industrial feel.</td>', 'Interesting choice of setup here. Being in what looks like a basement gives this a real industrial feel.', '2011-01-19 17:34:55.000000', NULL, 1),
(6288614, 930651, 114225, '<td valign="top">Stupendous! You really brought the standard Homer humor to the title.</td>', 'Stupendous! You really brought the standard Homer humor to the title.', '2011-01-19 17:36:00.000000', NULL, 1),
(6288616, 930348, 114225, '<td valign="top">Interesting viewpoint. I like how you look at things in a different way. Looks like you caught your tripod/camera in the reflective surface, which is breaking up the smoothness a bit.</td>', 'Interesting viewpoint. I like how you look at things in a different way. Looks like you caught your tripod/camera in the reflective surface, which is breaking up the smoothness a bit.', '2011-01-19 17:37:13.000000', NULL, 1),
(6288618, 930645, 114225, '<td valign="top">I feel like I''m about to be eaten by a grue! Thanks for bringing back that memory.<br/> <br/>In case you aren''t sure about the reference: //en.wikipedia.org/wiki/Zork</td>', 'I feel like I''m about to be eaten by a grue! Thanks for bringing back that memory. In case you aren''t sure about the reference: //en.wikipedia.org/wiki/Zork', '2011-01-19 17:38:33.000000', NULL, 1),
(6288620, 930513, 114225, '<td valign="top">Nicely done. Great job with the selective focus. It''s position in this photo makes us ponder top portion of the photo, then find the striking point of sharpness.</td>', 'Nicely done. Great job with the selective focus. It''s position in this photo makes us ponder top portion of the photo, then find the striking point of sharpness.', '2011-01-19 17:39:39.000000', NULL, 1),
(6288621, 930297, 114225, '<td valign="top">I like this quite a bit. I''m hoping your mentioned in your notes how you did this. My guess: low power to the lamp to ensure that the coil is only partially heated.</td>', 'I like this quite a bit. I''m hoping your mentioned in your notes how you did this. My guess: low power to the lamp to ensure that the coil is only partially heated.', '2011-01-19 17:40:31.000000', NULL, 1),
(6288622, 930221, 114225, '<td valign="top">Great use of repeating elements to draw us in. I do however wish the other lamps were lit, as that orange is really striking against the greys.</td>', 'Great use of repeating elements to draw us in. I do however wish the other lamps were lit, as that orange is really striking against the greys.', '2011-01-19 17:41:28.000000', NULL, 1),
(6288623, 930464, 114225, '<td valign="top">The crisp details in this photo are what really make this photo pop.</td>', 'The crisp details in this photo are what really make this photo pop.', '2011-01-19 17:42:54.000000', NULL, 1),
(6288624, 930028, 114225, '<td valign="top">Nicely done. I have played around with fiber optics lamps a bit too, but I normally end up using movement to bring it alive. I like how you instead chose to use strong diagonal lines.</td>', 'Nicely done. I have played around with fiber optics lamps a bit too, but I normally end up using movement to bring it alive. I like how you instead chose to use strong diagonal lines.', '2011-01-19 17:45:11.000000', NULL, 1),
(6288625, 930146, 114225, '<td valign="top">Wonderful take on the challenge. The colors and lighting are simply superb.</td>', 'Wonderful take on the challenge. The colors and lighting are simply superb.', '2011-01-19 17:45:56.000000', NULL, 1),
(6288627, 930257, 114225, '<td valign="top">This scene drags me into it, and won''t let go. I can feel the crisp/moist air around me, and smell the dead leaves.</td>', 'This scene drags me into it, and won''t let go. I can feel the crisp/moist air around me, and smell the dead leaves.', '2011-01-19 17:46:41.000000', NULL, 1),
(6288628, 930813, 114225, '<td valign="top">Great job bringing balance to this shot. The choice in macro is a good one, and I like how much depth of field you were able to obtain.</td>', 'Great job bringing balance to this shot. The choice in macro is a good one, and I like how much depth of field you were able to obtain.', '2011-01-19 17:47:36.000000', NULL, 1),
(6288719, 929893, 121082, '<td valign="top">Very nice Photo. i have no idea how you captured this shot but it is my favorite out of all. Great job. 9</td>', 'Very nice Photo. i have no idea how you captured this shot but it is my favorite out of all. Great job. 9', '2011-01-19 19:46:03.000000', NULL, 1),
(6288722, 930788, 121082, '<td valign="top">Nice Photo, very interesting, great colors and fantastic effects. 8</td>', 'Nice Photo, very interesting, great colors and fantastic effects. 8', '2011-01-19 19:47:19.000000', NULL, 1),
