(6289332, 930788, 100831, '<td valign="top">nifty.</td>', 'nifty.', '2011-01-20 12:40:35.000000', NULL, 1),
(6289342, 930513, 100831, '<td valign="top">I love the sharpness and composition of the wire holding that simple lamp. But the shadows and light are equally as interesting. Wonderful photograph, terrific b/w conversion, hope it does well!!</td>', 'I love the sharpness and composition of the wire holding that simple lamp. But the shadows and light are equally as interesting. Wonderful photograph, terrific b/w conversion, hope it does well!!', '2011-01-20 12:56:23.000000', NULL, 1),
(6289346, 930706, 100831, '<td valign="top">I love a good puddle and this <i>is</i> a good one!</td>', 'I love a good puddle and this is a good one!', '2011-01-20 12:57:09.000000', NULL, 1),
(6289356, 930249, 69034, '<td valign="top">The sky is a bit bland for this shot, but otherwise, love the idea and the angle of the shot.  It also might have worked for me better if the trees and signs weren''t in the back.</td>', 'The sky is a bit bland for this shot, but otherwise, love the idea and the angle of the shot.  It also might have worked for me better if the trees and signs weren''t in the back.', '2011-01-20 13:13:43.000000', NULL, 1),
(6289358, 929893, 69034, '<td valign="top">Excellent creativity.  Definite turn around against the rest of the challenge.</td>', 'Excellent creativity.  Definite turn around against the rest of the challenge.', '2011-01-20 13:14:31.000000', NULL, 1),
(6289359, 930691, 69034, '<td valign="top">I wnt to give you a score of 20 for including Optimus Prime in any challenge.  Unfortunately this shot is a bit glaring.  A small light source on OP might have helped a little. . .</td>', 'I wnt to give you a score of 20 for including Optimus Prime in any challenge.  Unfortunately this shot is a bit glaring.  A small light source on OP might have helped a little. . .', '2011-01-20 13:15:32.000000', NULL, 1),
(6289361, 930404, 69034, '<td valign="top">Interesting subject, and great color choice for the challenge.  It amazes me how little green is used.  Definitely adds a feel to the shot.</td>', 'Interesting subject, and great color choice for the challenge.  It amazes me how little green is used.  Definitely adds a feel to the shot.', '2011-01-20 13:16:32.000000', NULL, 1),
(6289362, 930348, 69034, '<td valign="top">Great composition.  Love the focus on the lamp, with the dof there.</td>', 'Great composition.  Love the focus on the lamp, with the dof there.', '2011-01-20 13:18:29.000000', NULL, 1),
(6289375, 930239, 69034, '<td valign="top">Kind of creepy.  Nice feeling on the shot.</td>', 'Kind of creepy.  Nice feeling on the shot.', '2011-01-20 13:29:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6289385, 930089, 43774, '<td valign="top">Love it!! This should be scoring very well. My #1 pick.</td>', 'Love it!! This should be scoring very well. My #1 pick.', '2011-01-20 13:56:55.000000', NULL, 1),
(6289452, 930640, 117804, '<td valign="top">My favorite so far... amazing lamp.</td>', 'My favorite so far... amazing lamp.', '2011-01-20 15:06:00.000000', NULL, 1),
(6289562, 930193, 76335, '<td valign="top">This the first image to come up for me in voting the Lamp challenge, and it''s screaming <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/31.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/31.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/31.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=88523" rel="nofollow" target="_blank">Iraklis</a>. Glad to see you''re still at it. The live lamps and dead fish seem to be moving (if dead fish can move) in opposite directions. The man anchors the scene. A great scene. Keep it up!</td>', 'This the first image to come up for me in voting the Lamp challenge, and it''s screaming  Iraklis. Glad to see you''re still at it. The live lamps and dead fish seem to be moving (if dead fish can move) in opposite directions. The man anchors the scene. A great scene. Keep it up!', '2011-01-20 17:20:40.000000', NULL, 1),
(6289567, 930432, 76335, '<td valign="top">The combination of rich warm tones and domestic textures is a winner.</td>', 'The combination of rich warm tones and domestic textures is a winner.', '2011-01-20 17:21:54.000000', NULL, 1),
(6289569, 930249, 76335, '<td valign="top">Great rhythm, nicely framed. Lighting feels a bit dull, flat.</td>', 'Great rhythm, nicely framed. Lighting feels a bit dull, flat.', '2011-01-20 17:22:26.000000', NULL, 1),
(6289571, 930625, 76335, '<td valign="top">So beautifully simple. A winner.</td>', 'So beautifully simple. A winner.', '2011-01-20 17:23:00.000000', NULL, 1),
(6289615, 930645, 76335, '<td valign="top">Wonderful job with the lighting.</td>', 'Wonderful job with the lighting.', '2011-01-20 18:27:03.000000', NULL, 1),
(6289742, 930038, 10785, '<td valign="top">The placement of the subjct in the frame seems a bit off. It''s sometimes good not to follow the rules but here doing so detracts from the compositoin leaving a large empty space at the top of the photo. Love the light. It''s got character. I also like how you gave the room a dark feel...</td>', 'The placement of the subjct in the frame seems a bit off. It''s sometimes good not to follow the rules but here doing so detracts from the compositoin leaving a large empty space at the top of the photo. Love the light. It''s got character. I also like how you gave the room a dark feel...', '2011-01-20 21:36:27.000000', NULL, 1),
(6289743, 929893, 10785, '<td valign="top">It would work better to either fill the frame with the subject or center the subject. Here, it''s not quite following the rule of thirds, it''s just off center. Good bright background and great that the bulb does not dissapear at the edges because you exposed well.</td>', 'It would work better to either fill the frame with the subject or center the subject. Here, it''s not quite following the rule of thirds, it''s just off center. Good bright background and great that the bulb does not dissapear at the edges because you exposed well.', '2011-01-20 21:38:44.000000', NULL, 1),
(6289745, 930207, 10785, '<td valign="top">Nice use of complimentary colors.</td>', 'Nice use of complimentary colors.', '2011-01-20 21:39:23.000000', NULL, 1),
(6289788, 930497, 124815, '<td valign="top">Directly from Edgar A. Poe! Splendid. 9</td>', 'Directly from Edgar A. Poe! Splendid. 9', '2011-01-20 23:36:45.000000', NULL, 1),
(6289790, 930257, 124815, '<td valign="top">Extreme gentleness! Like a Japanese print. Top 10.</td>', 'Extreme gentleness! Like a Japanese print. Top 10.', '2011-01-20 23:43:46.000000', NULL, 1),
(6289872, 930545, 69324, '<td valign="top">I like your composition, but it looks likes you might of bumped the contrast pretty hard.</td>', 'I like your composition, but it looks likes you might of bumped the contrast pretty hard.', '2011-01-21 06:01:35.000000', NULL, 1),
